/**
 * The material catalogue.
 *
 * Two kinds, because they answer different questions. A `plain` material is paint:
 * the colour comes entirely from the Look's tint, and the material only decides how
 * light leaves the surface. A `textured` material is cloth or timber: it carries its
 * own basecolor, normal and ORM maps, and the tint multiplies over them, which is
 * how you get the same weave in six colourways without six texture sets.
 *
 * Texture sets are the ones generated by product-viz/tools/make_fabrics.py, copied in
 * at build time. Adding a set means dropping three files in assets/materials and one
 * entry here.
 */

/* Every fabric ships two base colour maps.
 *
 *   <id>_basecolor.jpg   the cloth as woven and dyed, its own colour baked in
 *   <id>_weave.jpg       the same cloth with the dye divided out, mean near white
 *
 * The studio uses the weave map and multiplies the tint over it, so the colour a
 * person picks is the colour they get, and the same tint on two different fabrics
 * matches. `native` is the dye that was divided out, which is what the tint defaults
 * to when you first pick that fabric, so the cloth still starts out looking like
 * itself rather than like a swatch of grey.
 */
const FABRIC = (id, name, note, sheen, native) => ({
  id, name, note, kind: 'textured', sheen, native,
  basecolor: `${id}_weave.jpg`,
  swatchFile: `${id}_basecolor.jpg`,
  normal: `${id}_normal.png`,
  orm: `${id}_orm.jpg`,
});

export const MATERIALS = [
  // The product's own colour, recovered from the photograph. Only offered when the
  // reconstruction actually carried colour, which the Hunyuan3D path does not.
  {
    id: 'photo', name: 'From the photo', kind: 'photo',
    note: "The product's real colour, baked from the reconstruction.",
    // Matte on purpose. The photographed colour already carries the product's own
    // sheen, and a second, rendered sheen on top of it is most visible where the
    // colour is darkest: a near-black figurine came out grey under the studio lights
    // with every one of its vertices below 0.05 luminance. Roughness 0.9 leaves the
    // photograph's highlights as the only highlights.
    roughness: 0.9, metallic: 0, native: '#ffffff',
  },

  // paints: tintable, no maps, so they stay crisp at any tile scale
  { id: 'matte', name: 'Matte paint', note: 'Flat, no sheen. Reads as powder coat.', kind: 'plain', roughness: 0.85, metallic: 0 },
  { id: 'satin', name: 'Satin paint', note: 'A soft highlight. The safe default.', kind: 'plain', roughness: 0.45, metallic: 0 },
  { id: 'gloss', name: 'Gloss lacquer', note: 'Sharp reflections. Shows every dent.', kind: 'plain', roughness: 0.12, metallic: 0 },
  { id: 'metal', name: 'Brushed metal', note: 'Tint drives the alloy: warm for brass.', kind: 'plain', roughness: 0.35, metallic: 1 },
  { id: 'chrome', name: 'Polished chrome', note: 'Mirror. Needs something to reflect.', kind: 'plain', roughness: 0.05, metallic: 1 },

  // cloth: the four sets from the fabric library
  FABRIC('camel-boucle', 'Camel bouclé', 'Looped pile, high sheen lobe.', 0.6, '#9f7c56'),
  FABRIC('ink-velvet', 'Ink velvet', 'Dense nap, strong sheen.', 0.8, '#373f52'),
  FABRIC('ivory-linen', 'Ivory linen', 'Open plain weave, matte.', 0.15, '#d7d1c4'),
  FABRIC('sage-twill', 'Sage twill', 'Diagonal rib, low sheen.', 0.25, '#707e6c'),
];

/* ------------------------------------------------------------------ custom */
/* Cloths the person invented. The generator that makes their maps is the same one that
 * made the four above, so a custom fabric is not a lesser thing: it is the same weave
 * model with different numbers. They live in one JSON file next to the maps, which
 * keeps "what materials exist" answerable by looking rather than by running code. */
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const run = promisify(execFile);
const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const DIR = join(ROOT, 'assets', 'materials');
const STORE = join(DIR, 'custom.json');

export const WEAVES = ['plain', 'twill', 'satin', 'boucle', 'velvet'];

let custom = [];
export async function loadCustom() {
  try { custom = JSON.parse(await readFile(STORE, 'utf8')); }
  catch { custom = []; }
  return custom;
}

/** Make a new cloth. Returns its catalogue entry. */
export async function createMaterial({ name, weave, roughness, normalStrength, threads, native, sheen }) {
  if (!WEAVES.includes(weave)) throw new Error(`weave must be one of ${WEAVES.join(', ')}`);
  const clean = String(name || '').trim().slice(0, 40);
  if (!clean) throw new Error('a name is required');
  const id = 'c-' + clean.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
    + '-' + Math.random().toString(36).slice(2, 6);

  await mkdir(DIR, { recursive: true });
  await run('python', [join(ROOT, 'lib', 'weave.py'), DIR, id, weave,
    String(roughness), String(normalStrength), String(threads)], { maxBuffer: 1 << 24 });

  const entry = {
    id, name: clean, kind: 'textured', custom: true,
    note: `${weave}, ${threads} threads`,
    weaveKind: weave, roughness, normalStrength, threads,
    sheen: sheen ?? (weave === 'velvet' ? 0.8 : weave === 'boucle' ? 0.6 : 0.2),
    native: native || '#c9ccd8',
    basecolor: `${id}_weave.jpg`,
    swatchFile: `${id}_weave.jpg`,
    normal: `${id}_normal.png`,
    orm: `${id}_orm.jpg`,
  };
  custom = [...await loadCustom(), entry];
  await writeFile(STORE, JSON.stringify(custom, null, 2));
  return entry;
}

export async function deleteMaterial(id) {
  custom = (await loadCustom()).filter((m) => m.id !== id);
  await writeFile(STORE, JSON.stringify(custom, null, 2));
}

const all = () => [...MATERIALS, ...custom];

export function getMaterial(id) {
  return all().find((m) => m.id === id) || null;
}

/** What the studio needs to render the picker. Never send file paths to the client. */
export function catalogue() {
  return all().map(({ id, name, note, kind, sheen, native, roughness, metallic, custom: isCustom }) => ({
    custom: !!isCustom,
    id, name, note, kind,
    sheen: sheen ?? 0,
    native: native ?? null,
    roughness: roughness ?? null,
    metallic: metallic ?? null,
    // the swatch shows the cloth as dyed, because a grid of near-white weaves tells
    // you nothing about which fabric is which
    // a built-in shows its dyed swatch, because a grid of near-white weaves tells you
    // nothing; a custom cloth has no dyed version, so it shows the weave tinted by CSS
    swatch: kind === 'textured'
      ? `/materials/${isCustom ? `${id}_weave.jpg` : `${id}_basecolor.jpg`}` : null,
    // the photo material's swatch is per project, so the studio fills it in
    // what the studio actually renders and tints
    weave: kind === 'textured' ? `/materials/${id}_weave.jpg` : null,
  }));
}
